const TIMEOUT_MS=4e3;document.querySelectorAll(".blog-ad-slot, .blog-ad-card").forEach(e=>{const t=e.querySelector('[id^="yandex_rtb_"]');if(!t)return;let o=t.childNodes.length>0;if(o)return;const n=new MutationObserver(()=>{t.childNodes.length&&(o=!0,n.disconnect())});n.observe(t,{childList:!0}),setTimeout(()=>{n.disconnect(),o||(e.style.display="none")},4e3)});